(()=>{window.ST_=(key,v0,st,th,secs)=>{const idx=D.findIndex(d=>d._key===key);PT8.launch({mode:'mp',rally:true,track:idx,laps:1,humans:[{id:'ford',alt:0}],ai:[]});const Rc=RACE;Rc.state='race';Rc.green=true;const c=Rc.cars.find(q=>q.human);
